    my_path = observation.get('self_path', [])
    opp_path = observation.get('opponent_path', [])
    def safe(nx, ny):
        return 0 <= nx < w and 0 <= ny < h and [nx, ny] not in obstacles
    def move_towards(tx, ty):
        dx = 0
        dy = 0
        if tx > x: dx = 1
        elif tx < x: dx = -1
        if ty > y: dy = 1
        elif ty < y: dy = -1
        if safe(x + dx, y + dy):
            return [dx, dy]
        if dx != 0:
            if safe(x + dx, y):
                return [dx, 0]
        if dy != 0:
            if safe(x, y + dy):
                return [0, dy]
        return [0, 0]
